theorem homology.map_desc {V : Type u} [category_theory.category V]
	[category_theory.limits.has_zero_morphisms V] {A B C : V} {f : A ⟶ B}
	[category_theory.limits.has_image f] {g : B ⟶ C}
	[category_theory.limits.has_kernel g] (w : f ≫ g = 0) {A' B' C' : V}
	{f' : A' ⟶ B'} [category_theory.limits.has_image f'] {g' : B' ⟶ C'}
	[category_theory.limits.has_kernel g'] (w' : f' ≫ g' = 0)
	(α : category_theory.arrow.mk f ⟶ category_theory.arrow.mk f')
	[category_theory.limits.has_image_map α]
	(β : category_theory.arrow.mk g ⟶ category_theory.arrow.mk g')
	[category_theory.limits.has_cokernel (image_to_kernel f g w)]
	[category_theory.limits.has_cokernel (image_to_kernel f' g' w')]
	(p : α.right = β.left) {D : V}
	(k : ↑(category_theory.limits.kernel_subobject g') ⟶ D)
	(z : image_to_kernel f' g' w' ≫ k = 0) :
	homology.map w w' α β p ≫ homology.desc f' g' w' k z = homology.desc f g w (category_theory.limits.kernel_subobject_map β ≫ k) _ :=

